import { type DiagramScene, type DiagramPlacedItem } from './types';
import { estimateCardSize } from './metrics';
import { PAD } from './constants';
import { angle } from './geometry-ring';
import { frameFitScale, spatialFrame, unreadablySmall } from './spatial.ts';

export function layoutRadial(scene: DiagramScene, cardSizes: { width: number; height: number }[]) {
  const { width, height, start, order, center } = scene.options;
  const satellites = scene.items.filter((item) => item.id !== center);
  const sizes = scene.items.map(
    (item, i) => cardSizes[i] || estimateCardSize(item, item.id === center),
  );
  // Use the available horizontal space instead of clamping individual cards
  // against the frame, which destroys spacing when the orbit is too large.
  const stretchX = Math.max(
    1,
    (width - Math.max(...sizes.map((size) => size.width)) - PAD * 2) /
      Math.max(1, height - Math.max(...sizes.map((size) => size.height)) - PAD * 2),
  );
  let orbit = 0;
  const directions = scene.items.map((item) => {
    if (item.id === center) return { x: 0, y: 0 };
    const phi = angle(orbit++, satellites.length, start, order);
    return { x: Math.sin(phi) * stretchX, y: -Math.cos(phi) };
  });
  let minR = 0;
  let maxR = Infinity;
  for (let i = 0; i < sizes.length; i++) {
    const dir = directions[i];
    if (Math.abs(dir.x) > 1e-6)
      maxR = Math.min(maxR, (width / 2 - PAD - sizes[i].width / 2) / Math.abs(dir.x));
    if (Math.abs(dir.y) > 1e-6)
      maxR = Math.min(maxR, (height / 2 - PAD - sizes[i].height / 2) / Math.abs(dir.y));
    for (let j = 0; j < i; j++) {
      const dx = Math.abs(dir.x - directions[j].x);
      const dy = Math.abs(dir.y - directions[j].y);
      // Every pair must be separated along at least one axis, including
      // satellite pairs (not just each satellite and the central card).
      minR = Math.max(
        minR,
        Math.min(
          dx > 1e-6 ? ((sizes[i].width + sizes[j].width) / 2 + 28) / dx : Infinity,
          dy > 1e-6 ? ((sizes[i].height + sizes[j].height) / 2 + 28) / dy : Infinity,
        ),
      );
    }
  }
  const radius = Math.max(minR, Math.min(maxR, minR + 36));
  const items: DiagramPlacedItem[] = scene.items.map((item, i) => ({
    id: item.id,
    kind: 'card',
    x: width / 2 + directions[i].x * radius - sizes[i].width / 2,
    y: height / 2 + directions[i].y * radius - sizes[i].height / 2,
    ...sizes[i],
  }));
  const fitScale = frameFitScale(items, spatialFrame(width, height), PAD);
  const overflowReason = unreadablySmall(fitScale) ? ('read' as const) : undefined;
  return { items, fitScale, overflow: Boolean(overflowReason), overflowReason };
}

src/diagram/layout-field.ts.source:
import {
  clusterHaloContains,
  clusterHaloPath,
  leaderPath,
  overlaps,
  perimeterLink,
} from './geometry.ts';
import {
  estimateFieldLabel,
  estimateZoneLabel,
  placeAnchoredLabel,
  placeZoneLabel,
  textBox,
} from './labels.ts';
import {
  DOT,
  boxFromCenter,
  boxLeaves,
  normalize,
  plotCenter,
  semanticToDisplay,
  spatialFrame,
  type Box,
  type SemanticPoint,
  type SpatialFrame,
} from './spatial.ts';

export interface FieldItem {
  id: string;
  title: string;
  shape: 'vertex' | 'card' | 'dot';
  x: number;
  y: number;
  cluster: string;
}

export interface FieldZone {
  id: string;
  label: string;
  x: { min: number; max: number };
  y: { min: number; max: number };
}

export interface FieldCluster {
  id: string;
  title: string;
  tone: string;
}

export interface FieldScene {
  options: {
    width: number;
    height: number;
    guide: 'none' | 'axes';
    xLow: string;
    xHigh: string;
    yLow: string;
    yHigh: string;
    clusterRegion: 'none' | 'halo';
  };
  items: FieldItem[];
  links: { from: string; to: string; kind: 'undirected' | 'forward' | 'both'; label: string }[];
  zones: FieldZone[];
  clusters: FieldCluster[];
}

export interface FieldGuide {
  kind: 'axis' | 'label';
  path?: string;
  text?: string;
  x?: number;
  y?: number;
  anchor?: 'start' | 'middle' | 'end';
}

export interface FieldRegion {
  id: string;
  kind: 'zone' | 'cluster';
  label: string;
  tone: string;
  box: Box;
  labelBox?: Box;
  path?: string;
  marks?: { x: number; y: number; r: number }[];
}

function itemSize(item: FieldItem, cards: { width: number; height: number }[], index: number) {
  if (item.shape === 'card') return cards[index] || { width: 168, height: 75 };
  if (item.shape === 'vertex') return { width: 72, height: 72 };
  return { width: DOT, height: DOT };
}

function preferredDir(semantic: SemanticPoint) {
  if (Math.hypot(semantic.x, semantic.y) < 1e-6) return { x: 0, y: -1 };
  return normalize(semantic.x, -semantic.y);
}

export function layoutField(
  scene: FieldScene,
  measured: {
    labels?: { width: number; height: number }[];
    cards?: { width: number; height: number }[];
  } = {},
) {
  const { width, height, guide, clusterRegion } = scene.options;
  const labelSizes = measured.labels || [];
  const cardSizes = measured.cards || [];
  const hasLegend = scene.items.some((item) => item.cluster);
  const frame: SpatialFrame = spatialFrame(width, height, {
    bottom: hasLegend ? 88 : 56,
  });
  const nodes = scene.items.map((item, i) => {
    const semantic = { x: item.x, y: item.y };
    const kind = item.shape === 'card' ? 'card' : item.shape === 'vertex' ? 'vertex' : 'dot';
    return {
      id: item.id,
      kind: kind as 'card' | 'vertex' | 'dot',
      ...boxFromCenter(semanticToDisplay(semantic, frame), itemSize(item, cardSizes, i)),
      semantic,
      cluster: item.cluster,
    };
  });

  const zones = layoutZones(scene.zones, frame);
  const guides = guide === 'axes' ? layoutAxes(frame, scene.options) : [];
  const origin = plotCenter(frame);
  const obstacles: Box[] = [
    ...nodes,
    ...guides.flatMap((mark) =>
      mark.text ? [textBox(mark.text, mark.x || 0, mark.y || 0, mark.anchor || 'middle')] : [],
    ),
  ];
  let overflow = nodes.some((node) => boxLeaves(node, frame, 2));
  for (const zone of zones) {
    if (!zone.label) continue;
    const prefer = {
      x: zone.box.x + zone.box.width / 2 < origin.x ? -1 : 1,
      y: zone.box.y + zone.box.height / 2 < origin.y ? 1 : -1,
    };
    const result = placeZoneLabel(
      zone.box,
      estimateZoneLabel(zone.label),
      prefer,
      obstacles,
      frame,
    );
    zone.labelBox = result.box;
    obstacles.push({
      x: result.box.x - 10,
      y: result.box.y - 8,
      width: result.box.width + 20,
      height: result.box.height + 16,
    });
    overflow = overflow || result.overflow || boxLeaves(result.box, frame, 2);
  }
  const placed = nodes.map((node, i) => {
    if (node.kind === 'card') return { ...node, label: undefined, labelGap: 0 };
    const size = labelSizes[i] || estimateFieldLabel(scene.items[i].title);
    const preferred = preferredDir(node.semantic);
    const result = placeAnchoredLabel(
      semanticToDisplay(node.semantic, frame),
      size,
      preferred,
      obstacles,
      frame,
    );
    obstacles.push(result.box);
    overflow = overflow || result.overflow || boxLeaves(result.box, frame, 2);
    for (const other of nodes) {
      if (other.id !== node.id && overlaps(result.box, other, 4)) overflow = true;
    }
    return { ...node, label: result.box, labelGap: result.gap };
  });

  const byId = new Map(placed.map((item) => [item.id, item]));
  const links = scene.links.flatMap((link) => {
    const from = byId.get(link.from);
    const to = byId.get(link.to);
    if (!from || !to) return [];
    const geometry = perimeterLink(from, to, {
      from: from.kind === 'dot' || from.kind === 'vertex' ? 'circle' : 'box',
      to: to.kind === 'dot' || to.kind === 'vertex' ? 'circle' : 'box',
    });
    if (!geometry) return [];
    return [{ ...link, path: geometry.path, labelAt: geometry.labelAt }];
  });
  const noteLinks = placed.flatMap((item) => {
    if (!item.label || item.labelGap <= 12) return [];
    const path = leaderPath(item, item.label, item.kind !== 'card');
    return path ? [{ itemId: item.id, path, kind: 'leader' as const }] : [];
  });
  const clusterHalos =
    clusterRegion === 'halo'
      ? layoutClusterHalos(placed, scene.clusters)
      : { regions: [] as FieldRegion[], overflow: false };

  return {
    items: placed,
    links,
    noteLinks,
    overflow: overflow || clusterHalos.overflow,
    frame,
    regions: [...zones, ...clusterHalos.regions],
    guides,
    legend: legendFor(scene),
  };
}

export function layoutZones(zones: FieldZone[], frame: SpatialFrame): FieldRegion[] {
  return zones.map((zone) => {
    const a = semanticToDisplay({ x: zone.x.min, y: zone.y.max }, frame);
    const b = semanticToDisplay({ x: zone.x.max, y: zone.y.min }, frame);
    return {
      id: zone.id,
      kind: 'zone' as const,
      label: zone.label,
      tone: 'muted',
      box: { x: a.x, y: a.y, width: b.x - a.x, height: b.y - a.y },
    };
  });
}

export function layoutClusterHalos(
  items: {
    id: string;
    cluster?: string;
    x: number;
    y: number;
    width: number;
    height: number;
  }[],
  clusters: FieldCluster[],
): { regions: FieldRegion[]; overflow: boolean } {
  const titles = new Map(clusters.map((cluster) => [cluster.id, cluster]));
  const groups = new Map<string, { x: number; y: number }[]>();
  const membership = items.map((item) => ({
    cluster: item.cluster,
    point: { x: item.x + item.width / 2, y: item.y + item.height / 2 },
  }));
  for (const item of membership) {
    if (!item.cluster) continue;
    const points = groups.get(item.cluster) || [];
    points.push(item.point);
    groups.set(item.cluster, points);
  }
  const regions: FieldRegion[] = [];
  let overflow = false;
  for (const [id, points] of groups) {
    const swallowed = membership.some(
      (item) => item.cluster && item.cluster !== id && clusterHaloContains(item.point, points),
    );
    if (swallowed) {
      overflow = true;
      continue;
    }
    const blob = clusterHaloPath(points);
    regions.push({
      id,
      kind: 'cluster',
      label: titles.get(id)?.title || id,
      tone: titles.get(id)?.tone || 'muted',
      box: blob.box,
      path: blob.path,
    });
  }
  return { regions, overflow };
}

export function layoutAxes(
  frame: SpatialFrame,
  labels: { xLow: string; xHigh: string; yLow: string; yHigh: string },
): FieldGuide[] {
  const origin = plotCenter(frame);
  const left = semanticToDisplay({ x: -1, y: 0 }, frame);
  const right = semanticToDisplay({ x: 1, y: 0 }, frame);
  const top = semanticToDisplay({ x: 0, y: 1 }, frame);
  const bottom = semanticToDisplay({ x: 0, y: -1 }, frame);
  const guides: FieldGuide[] = [
    { kind: 'axis', path: `M ${left.x} ${origin.y} L ${right.x} ${origin.y}` },
    { kind: 'axis', path: `M ${origin.x} ${top.y} L ${origin.x} ${bottom.y}` },
  ];
  if (labels.xLow)
    guides.push({
      kind: 'label',
      text: labels.xLow,
      x: left.x + 4,
      y: origin.y + 22,
      anchor: 'start',
    });
  if (labels.xHigh)
    guides.push({
      kind: 'label',
      text: labels.xHigh,
      x: right.x - 4,
      y: origin.y + 22,
      anchor: 'end',
    });
  if (labels.yHigh)
    guides.push({
      kind: 'label',
      text: labels.yHigh,
      x: origin.x,
      y: top.y - 10,
      anchor: 'middle',
    });
  if (labels.yLow)
    guides.push({
      kind: 'label',
      text: labels.yLow,
      x: origin.x,
      y: bottom.y + 22,
      anchor: 'middle',
    });
  return guides;
}

function legendFor(scene: FieldScene) {
  const seen = new Map<string, { id: string; title: string; tone: string }>();
  const declared = new Map(scene.clusters.map((cluster) => [cluster.id, cluster]));
  const tones = ['accent', 'muted', 'ink', 'soft'];
  let next = 0;
  for (const item of scene.items) {
    if (!item.cluster || seen.has(item.cluster)) continue;
    const declaredCluster = declared.get(item.cluster);
    seen.set(item.cluster, {
      id: item.cluster,
      title: declaredCluster?.title || item.cluster,
      tone: declaredCluster?.tone || tones[next++ % tones.length],
    });
  }
  return [...seen.values()];
}

