import type { Box } from './spatial.ts';

export interface SpatialGuide {
  kind: 'axis' | 'label';
  path?: string;
  text?: string;
  x?: number;
  y?: number;
  anchor?: 'start' | 'middle' | 'end';
}

export interface SpatialRegion {
  id: string;
  kind: 'zone' | 'cluster';
  label: string;
  tone: string;
  box: Box;
  labelBox?: Box;
  path?: string;
  marks?: { x: number; y: number; r: number }[];
}

export function regionRect(box: Box) {
  return {
    x: box.x,
    y: box.y,
    width: Math.max(1, box.width),
    height: Math.max(1, box.height),
  };
}

export function spatialSignature(input: {
  overflow: boolean;
  fitScale?: number;
  items: { x: number; y: number; label?: Box; note?: Box }[];
  regions?: SpatialRegion[];
  guides?: SpatialGuide[];
  noteLinks?: { path: string }[];
  links?: { path: string }[];
}) {
  return JSON.stringify({
    o: input.overflow,
    s: input.fitScale ?? 1,
    n: (input.noteLinks || []).map((link) => link.path),
    e: (input.links || []).map((link) => link.path),
    r: (input.regions || []).map((region) => [
      region.id,
      Math.round(region.box.x),
      Math.round(region.box.y),
      Math.round(region.box.width),
      Math.round(region.box.height),
      region.labelBox && [
        Math.round(region.labelBox.x),
        Math.round(region.labelBox.y),
        Math.round(region.labelBox.width),
        Math.round(region.labelBox.height),
      ],
      region.path ||
        (region.marks || []).map((mark) => [
          Math.round(mark.x),
          Math.round(mark.y),
          Math.round(mark.r),
        ]),
    ]),
    g: (input.guides || []).map((guide) => guide.path || `${guide.text}:${guide.x}:${guide.y}`),
    i: input.items.map((item) => [
      Math.round(item.x),
      Math.round(item.y),
      item.label && [
        Math.round(item.label.x),
        Math.round(item.label.y),
        Math.round(item.label.width),
        Math.round(item.label.height),
      ],
      item.note && [
        Math.round(item.note.x),
        Math.round(item.note.y),
        Math.round(item.note.width),
        Math.round(item.note.height),
      ],
    ]),
  });
}

src/diagram/to-canvas.ts.source:
import { type CanvasArrows, type CanvasScene } from '../canvas/types.ts';
import { resolvedLinks } from './links';
import { type DiagramLinkKind, type DiagramScene } from './types';

function arrowsFor(kind: DiagramLinkKind): CanvasArrows {
  return kind === 'both' ? 'both' : kind === 'forward' ? 'end' : 'none';
}

export function toCanvasScene(scene: DiagramScene): CanvasScene {
  const links = resolvedLinks(scene);
  return {
    options: {
      layout: 'flow',
      direction: scene.options.direction,
      width: scene.options.width,
      height: scene.options.height,
      autoHeight: scene.options.autoHeight,
      gap: scene.options.gap,
      route: scene.options.route,
    },
    nodes: scene.items.map((item) => ({
      id: item.id,
      markdown: item.markdown ? `### ${item.title}\n\n${item.markdown}` : `### ${item.title}`,
      shape: item.shape === 'vertex' ? 'ellipse' : 'card',
      fill: 'solid' as const,
      tone:
        item.level === 'high'
          ? 'accent'
          : item.level === 'medium'
            ? 'muted'
            : item.level === 'low'
              ? 'default'
              : 'default',
      width: scene.options.nodeWidth,
      dx: 0,
      dy: 0,
      pinned: false,
    })),
    edges: links.map((link) => ({
      from: link.from,
      to: link.to,
      label: link.label,
      tone: 'default' as const,
      dashed: false,
      arrows: arrowsFor(link.kind),
      shape: 'line' as const,
      inset: link.inset,
    })),
  };
}

src/drafts.ts.source:
import { cacheGet, cacheSet } from './cache';
import { SourceStore, normalize, type Block } from './source';
import type { Autosaver } from './save';

type DraftBlock = Pick<Block, 'id' | 'kind' | 'name' | 'text'>;
export interface Draft {
  version: 1;
  base: string;
  content: string;
  blocks: DraftBlock[];
  when: number;
  reason: 'edit' | 'hidden' | 'conflict' | 'saved';
}
function blockFingerprint(blocks: Iterable<Pick<Block, 'id' | 'kind' | 'name' | 'text'>>) {
  let a = 0x811c9dc5,
    b = 0x9e3779b9,
    length = 0;
  const feed = (value: string) => {
    const s = value.length + ':' + value;
    length += s.length;
    for (let i = 0; i < s.length; i++) {
      const c = s.charCodeAt(i);
      a = Math.imul(a ^ c, 0x01000193);
      b = Math.imul((b ^ c) >>> 0, 0x85ebca6b);
      b ^= b >>> 13;
    }
  };
  let count = 0;
  for (const block of blocks) {
    count++;
    feed(block.id);
    feed(block.kind);
    feed(block.name);
    feed(normalize(block.text));
  }
  return `${count}:${length}:${(a >>> 0).toString(16)}:${(b >>> 0).toString(16)}`;
}

type DraftStorage = 'active' | 'conflict';
interface Cache {
  get: (key: string) => Promise<unknown>;
  set: (key: string, value: unknown) => Promise<boolean>;
}

export class DraftStore {
  private base: string;
  private keys: Record<DraftStorage | 'previous', string>;

  constructor(
    cacheKey: string,
    private store: SourceStore,
    baseline: Block[],
    private cache: Cache = { get: cacheGet, set: cacheSet },
  ) {
    this.base = blockFingerprint(baseline);
    this.keys = {
      active: 'draft:' + cacheKey,
      conflict: 'conflict:' + cacheKey,
      previous: 'previous:' + cacheKey,
    };
  }

  rebase(blocks: Block[]) {
    this.base = blockFingerprint(blocks);
  }

  async persist(reason: Draft['reason'] = 'edit'): Promise<Draft | null> {
    const blocks = this.store.list().map(({ id, kind, name, text }) => ({ id, kind, name, text }));
    const draft: Draft = {
      version: 1,
      base: this.base,
      content: blockFingerprint(blocks),
      blocks,
      when: Date.now(),
      reason,
    };
    return (await this.cache.set(this.keys.active, draft)) ? draft : null;
  }

  discard(storage: DraftStorage = 'active') {
    return this.cache.set(this.keys[storage], undefined);
  }

  async archive(saver: Pick<Autosaver, 'state' | 'dirty'>) {
    const draft = (await this.cache.get(this.keys.active)) as Draft | undefined;
    if (
      !draft?.blocks?.length ||
      saver.state !== 'saved' ||
      saver.dirty() ||
      draft.content !== blockFingerprint(this.store.list())
    )
      return;
    if (await this.cache.set(this.keys.previous, { ...draft, reason: 'saved' } satisfies Draft)) {
      await this.discard();
    }
  }

  async preserveConflict() {
    const draft = await this.persist('conflict');
    if (!draft || !(await this.cache.set(this.keys.conflict, draft))) return false;
    await this.discard();
    return true;
  }

  async recovery() {
    const active = (await this.cache.get(this.keys.active)) as Draft | undefined;
    const conflict = (await this.cache.get(this.keys.conflict)) as Draft | undefined;
    const draft = active?.blocks?.length ? active : conflict?.blocks?.length ? conflict : undefined;
    if (
      draft &&
      JSON.stringify(draft.blocks.map((b) => [b.id, b.text])) !==
        JSON.stringify(this.store.list().map((b) => [b.id, b.text]))
    ) {
      return {
        draft,
        storage: (active?.blocks?.length ? 'active' : 'conflict') as DraftStorage,
        changedBase: Boolean(draft.base && draft.base !== blockFingerprint(this.store.list())),
      };
    }
    if (active?.blocks?.length) await this.discard();
    return null;
  }

  restore(draft: Draft) {
    const ids = new Set(draft.blocks.map((b) => b.id));
    for (const block of draft.blocks) {
      if (this.store.blocks.has(block.id)) this.store.setText(block.id, block.text);
      else this.store.add(block);
    }
    for (const block of this.store.list()) {
      if (!ids.has(block.id) && block.id !== 'manifest') this.store.remove(block.id);
    }
    let before: string | null = null;
    for (const id of draft.blocks
      .filter((b) => b.kind === 'slide')
      .map((b) => b.id)
      .reverse()) {
      this.store.moveBefore(id, before);
      before = id;
    }
  }
}

src/editor.ts.source:
import {
  autocompletion,
  closeBrackets,
  closeBracketsKeymap,
  completionKeymap,
} from '@codemirror/autocomplete';
import { defaultKeymap, history, historyKeymap, indentWithTab } from '@codemirror/commands';
import { json as jsonLanguage } from '@codemirror/lang-json';
import { markdown } from '@codemirror/lang-markdown';
import {
  bracketMatching,
  defaultHighlightStyle,
  foldGutter,
  foldKeymap,
  indentOnInput,
  syntaxHighlighting,
} from '@codemirror/language';
import { highlightSelectionMatches, searchKeymap } from '@codemirror/search';
import { EditorState, StateField, type Text } from '@codemirror/state';
import {
  crosshairCursor,
  Decoration,
  drawSelection,
  dropCursor,
  EditorView,
  highlightActiveLine,
  highlightActiveLineGutter,
  highlightSpecialChars,
  keymap,
  lineNumbers,
  rectangularSelection,
  type DecorationSet,
} from '@codemirror/view';
import { normalize, type Block } from './source';

function hiddenSlideMetadata(doc: Text): DecorationSet {
  const match = /^(?:\s*<!--\s*milo:[\s\S]*?-->[ \t]*(?:\r?\n)?)/.exec(doc.toString());
  return match
    ? Decoration.set([Decoration.replace({}).range(0, match[0].length)])
    : Decoration.none;
}

const editorSetup = [
  lineNumbers(),
  highlightActiveLineGutter(),
  highlightSpecialChars(),
  history(),
  foldGutter(),
  drawSelection(),
  dropCursor(),
  EditorState.allowMultipleSelections.of(true),
  indentOnInput(),
  syntaxHighlighting(defaultHighlightStyle, { fallback: true }),
  bracketMatching(),
  closeBrackets(),
  autocompletion(),
  rectangularSelection(),
  crosshairCursor(),
  highlightActiveLine(),
  highlightSelectionMatches(),
  keymap.of([
    ...closeBracketsKeymap,
    ...defaultKeymap,
    ...searchKeymap,
    ...historyKeymap,
    ...foldKeymap,
    ...completionKeymap,
  ]),
];
const slideMarkdown = markdown({ completeHTMLTags: false });
const hiddenSlideMetadataField = StateField.define<DecorationSet>({
  create: (state) => hiddenSlideMetadata(state.doc),
  update: (decorations, transaction) =>
    transaction.docChanged ? hiddenSlideMetadata(transaction.newDoc) : decorations,
  provide: (field) => EditorView.decorations.from(field),
});
export class SourceEditor {
  private view: EditorView | null = null;
  private syncing = false;

  mount(parent: HTMLElement, block: Block, onChange: (text: string) => void) {
    this.destroy();
    const state = EditorState.create({
      doc: block.text,
      extensions: [
        editorSetup,
        block.kind === 'slide' ? slideMarkdown : jsonLanguage(),
        keymap.of([indentWithTab]),
        EditorView.lineWrapping,
        ...(block.kind === 'slide' ? [hiddenSlideMetadataField] : []),
        EditorState.lineSeparator.of(block.text.includes('\r\n') ? '\r\n' : '\n'),
        EditorView.contentAttributes.of({ 'aria-label': block.name + ' のソース' }),
        EditorView.updateListener.of((update) => {
          if (update.docChanged && !this.syncing) onChange(update.state.sliceDoc());
        }),
      ],
    });
    this.view = new EditorView({ state, parent });
  }

  sync(text: string) {
    if (!this.view) return;
    const next = normalize(text),
      old = this.view.state.doc.toString();
    if (next === old) return;
    let from = 0;
    while (from < old.length && from < next.length && old[from] === next[from]) from++;
    let oldEnd = old.length,
      newEnd = next.length;
    while (oldEnd > from && newEnd > from && old[oldEnd - 1] === next[newEnd - 1]) {
      oldEnd--;
      newEnd--;
    }
    this.syncing = true;
    try {
      this.view.dispatch({ changes: { from, to: oldEnd, insert: next.slice(from, newEnd) } });
    } finally {
      this.syncing = false;
    }
  }

  destroy() {
    this.view?.destroy();
    this.view = null;
  }
}

src/flow/align.ts.source:
import { FLOW, type FlowFrame, type FlowGraph, type FlowRanked } from './types.ts';

/** Ordering constraints between aligned blocks; null means a cyclic or overlapping alignment. */
function separationConstraints(
  candidate: number[],
  ranks: number[][],
  crossSizes: number[],
  gap: number,
) {
  const edges = new Map<number, Map<number, number>>();
  for (const id of candidate) edges.set(id, new Map());
  for (const members of ranks) {
    // An alignment block may contain only one node per rank.
    if (new Set(members.map((i) => candidate[i])).size !== members.length) return null;
    for (let j = 1; j < members.length; j++) {
      const a = members[j - 1],
        b = members[j];
      const distance = (crossSizes[a] + crossSizes[b]) / 2 + gap;
      const next = edges.get(candidate[a])!;
      next.set(candidate[b], Math.max(next.get(candidate[b]) || 0, distance));
    }
  }
  const degree = new Map([...edges.keys()].map((id) => [id, 0]));
  for (const next of edges.values())
    for (const id of next.keys()) degree.set(id, degree.get(id)! + 1);
  const order = [...degree.keys()].filter((id) => degree.get(id) === 0);
  for (let i = 0; i < order.length; i++)
    for (const id of edges.get(order[i])!.keys()) {
      degree.set(id, degree.get(id)! - 1);
      if (degree.get(id) === 0) order.push(id);
    }
  return order.length === edges.size ? { edges, order } : null;
}

/** Align central branches across ranks, then compact without changing rank order. */
export function alignBranches(
  graph: FlowGraph,
  ranked: FlowRanked,
  frames: Map<string, FlowFrame>,
  height: number,
  gap: number,
) {
  if (graph.route !== 'auto' || graph.nodes.some((node) => node.pinned || node.dx || node.dy))
    return { frames, height };
  const horizontal = graph.direction === 'right' || graph.direction === 'left';
  const crossSize = (box: FlowFrame) => (horizontal ? box.height : box.width);
  const crossCenter = (box: FlowFrame) => (horizontal ? box.y : box.x) + crossSize(box) / 2;
  const index = new Map(graph.nodes.map((node, i) => [node.id, i]));
  let blocks = graph.nodes.map((_, i) => i);
  const crossSizes = graph.nodes.map((node) => crossSize(frames.get(node.id)!));
  const constraints = (candidate: number[]) =>
    separationConstraints(candidate, ranked.groups, crossSizes, gap);
  const join = (a: number, b: number) => {
    if (blocks[a] === blocks[b]) return;
    const candidate = blocks.map((id) => (id === blocks[b] ? blocks[a] : id));
    // Crossing median constraints must never invert or overlap a rank.
    if (constraints(candidate)) blocks = candidate;
  };
  const outgoing = new Map<number, number[]>(),
    incoming = new Map<number, number[]>();
  for (const edge of graph.edges) {
    const a = index.get(edge.from)!,
      b = index.get(edge.to)!;
    if (edge.feedback || (edge.route && edge.route !== 'auto')) continue;
    outgoing.set(a, [...new Set([...(outgoing.get(a) || []), b])]);
    incoming.set(b, [...new Set([...(incoming.get(b) || []), a])]);
  }
  for (const groups of [outgoing, incoming])
    for (const neighbors of groups.values()) {
      neighbors.sort(
        (a, b) =>
          crossCenter(frames.get(graph.nodes[a].id)!) - crossCenter(frames.get(graph.nodes[b].id)!),
      );
    }
  const median = (neighbors: number[]) =>
    neighbors.length % 2 ? neighbors[Math.floor(neighbors.length / 2)] : undefined;
  for (const [node, neighbors] of outgoing) {
    const next = median(neighbors);
    if (next !== undefined && median(incoming.get(next)!) === node) join(node, next);
  }
  const { edges, order } = constraints(blocks)!;
  const positions = new Map(order.map((id) => [id, 0]));
  for (const id of order)
    for (const [next, distance] of edges.get(id)!)
      positions.set(next, Math.max(positions.get(next)!, positions.get(id)! + distance));

  const blockCounts = new Map<number, number>();
  for (const id of blocks) blockCounts.set(id, (blockCounts.get(id) || 0) + 1);

  // For even fan-outs / fan-ins, center an unconstrained node between the two
  // middle neighbors. Bound it by the same rank-separation constraints.
  for (const groups of [incoming, outgoing])
    for (const [node, neighbors] of groups) {
      if (neighbors.length % 2 || blockCounts.get(blocks[node]) !== 1) continue;
      const middle = neighbors.length / 2;
      const wanted =
        (positions.get(blocks[neighbors[middle - 1]])! +
          positions.get(blocks[neighbors[middle]])!) /
        2;
      let low = -Infinity,
        high = Infinity;
      for (const [before, next] of edges)
        if (next.has(blocks[node]))
          low = Math.max(low, positions.get(before)! + next.get(blocks[node])!);
      for (const [after, distance] of edges.get(blocks[node])!)
        high = Math.min(high, positions.get(after)! - distance);
      positions.set(blocks[node], Math.min(high, Math.max(low, wanted)));
    }
  const centers = graph.nodes.map((_, i) => positions.get(blocks[i])!);
  const lo = Math.min(
    ...graph.nodes.map((node, i) => centers[i] - crossSize(frames.get(node.id)!) / 2),
  );
  const hi = Math.max(
    ...graph.nodes.map((node, i) => centers[i] + crossSize(frames.get(node.id)!) / 2),
  );
  const required = hi - lo + FLOW.PADDING * 2;
  const crossLimit = horizontal ? height : graph.width;
  // Fixed frames retain their existing placement when alignment would require
  // additional space. Auto-height diagrams can grow to preserve separation.
  if (required > crossLimit && !(horizontal && graph.autoHeight)) return { frames, height };
  const nextHeight =
    horizontal && graph.autoHeight ? Math.max(height, Math.ceil(required)) : height;
  const offset = ((horizontal ? nextHeight : graph.width) - (hi - lo)) / 2 - lo;
  const aligned = new Map<string, FlowFrame>();
  graph.nodes.forEach((node, i) => {
    const box = frames.get(node.id)!;
    const cross = centers[i] + offset - crossSize(box) / 2;
    aligned.set(node.id, { ...box, ...(horizontal ? { y: cross } : { x: cross }) });
  });
  return { frames: aligned, height: nextHeight };
}

src/flow/geometry.ts.source:
import type { FlowFrame } from './types.ts';

export type Side = 'top' | 'right' | 'bottom' | 'left';
export type Point = { x: number; y: number };

export function portPoint(frame: FlowFrame, side: Side, t: number): Point {
  const x0 = frame.x;
  const y0 = frame.y;
  const x1 = frame.x + frame.width;
  const y1 = frame.y + frame.height;
  const along = Math.min(0.85, Math.max(0.15, t));
  if (side === 'top') return { x: x0 + frame.width * along, y: y0 };
  if (side === 'bottom') return { x: x0 + frame.width * along, y: y1 };
  if (side === 'left') return { x: x0, y: y0 + frame.height * along };
  return { x: x1, y: y0 + frame.height * along };
}

export function inflate(box: FlowFrame, pad: number): FlowFrame {
  return {
    x: box.x - pad,
    y: box.y - pad,
    width: box.width + pad * 2,
    height: box.height + pad * 2,
  };
}

// Clip the segment against both closed axis intervals. Unlike strict
// segment/segment crossing, this also catches tangencies and collinear edges.
function segmentHits(a: Point, b: Point, box: FlowFrame) {
  let entry = 0,
    exit = 1;
  for (const [origin, delta, low, high] of [
    [a.x, b.x - a.x, box.x, box.x + box.width],
    [a.y, b.y - a.y, box.y, box.y + box.height],
  ]) {
    if (delta === 0) {
      if (origin < low || origin > high) return false;
      continue;
    }
    const t0 = (low - origin) / delta;
    const t1 = (high - origin) / delta;
    entry = Math.max(entry, Math.min(t0, t1));
    exit = Math.min(exit, Math.max(t0, t1));
    if (entry > exit) return false;
  }
  return true;
}

export function polylineHits(points: Point[], obstacles: FlowFrame[]) {
  for (let i = 0; i < points.length - 1; i += 1) {
    if (obstacles.some((box) => segmentHits(points[i], points[i + 1], box))) return true;
  }
  return false;
}

function cubicPoint(p0: Point, p1: Point, p2: Point, p3: Point, t: number): Point {
  const u = 1 - t;
  return {
    x: u ** 3 * p0.x + 3 * u ** 2 * t * p1.x + 3 * u * t ** 2 * p2.x + t ** 3 * p3.x,
    y: u ** 3 * p0.y + 3 * u ** 2 * t * p1.y + 3 * u * t ** 2 * p2.y + t ** 3 * p3.y,
  };
}

function quadPoint(p0: Point, p1: Point, p2: Point, t: number): Point {
  const u = 1 - t;
  return {
    x: u * u * p0.x + 2 * u * t * p1.x + t * t * p2.x,
    y: u * u * p0.y + 2 * u * t * p1.y + t * t * p2.y,
  };
}

export function cubicControls(start: Point, end: Point) {
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const horizontal = Math.abs(dx) >= Math.abs(dy);
  const bend = horizontal ? Math.max(35, Math.abs(dx) * 0.42) : Math.max(35, Math.abs(dy) * 0.42);
  return horizontal
    ? {
        c1: { x: start.x + Math.sign(dx || 1) * bend, y: start.y },
        c2: { x: end.x - Math.sign(dx || 1) * bend, y: end.y },
      }
    : {
        c1: { x: start.x, y: start.y + Math.sign(dy || 1) * bend },
        c2: { x: end.x, y: end.y - Math.sign(dy || 1) * bend },
      };
}

export function sampleCubic(p0: Point, c1: Point, c2: Point, p3: Point, steps = 12) {
  return Array.from({ length: steps + 1 }, (_, i) => cubicPoint(p0, c1, c2, p3, i / steps));
}

export function sampleQuad(p0: Point, c1: Point, p2: Point, steps = 12) {
  return Array.from({ length: steps + 1 }, (_, i) => quadPoint(p0, c1, p2, i / steps));
}

function numbersOf(body: string) {
  return [...body.matchAll(/[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?/g)].map((match) =>
    Number(match[0]),
  );
}

function samplePath(path: string): Point[] {
  const points: Point[] = [];
  let current = { x: 0, y: 0 };
  for (const match of path.matchAll(/([MLQC])([^MLQC]*)/g)) {
    const nums = numbersOf(match[2]);
    if ((match[1] === 'M' || match[1] === 'L') && nums.length >= 2) {
      current = { x: nums[0], y: nums[1] };
      points.push(current);
      continue;
    }
    if (match[1] === 'C' && nums.length >= 6) {
      const c1 = { x: nums[0], y: nums[1] };
      const c2 = { x: nums[2], y: nums[3] };
      const end = { x: nums[4], y: nums[5] };
      points.push(...sampleCubic(current, c1, c2, end).slice(1));
      current = end;
      continue;
    }
    if (match[1] === 'Q' && nums.length >= 4) {
      const control = { x: nums[0], y: nums[1] };
      const end = { x: nums[2], y: nums[3] };
      points.push(...sampleQuad(current, control, end).slice(1));
      current = end;
    }
  }
  return points;
}

export function graphBounds(frames: FlowFrame[]): FlowFrame {
  const xs = frames.map((frame) => frame.x);
  const ys = frames.map((frame) => frame.y);
  const rights = frames.map((frame) => frame.x + frame.width);
  const bottoms = frames.map((frame) => frame.y + frame.height);
  const x = Math.min(...xs);
  const y = Math.min(...ys);
  return { x, y, width: Math.max(...rights) - x, height: Math.max(...bottoms) - y };
}

export function edgeHitsNode(path: string, box: FlowFrame) {
  return polylineHits(samplePath(path), [inflate(box, 1)]);
}

const MIN_FLOATING_ARROW = 22;

/** Pull both ends of a segment toward its middle, leaving the arrow in the gap. */
export function insetEndpoints(start: Point, end: Point, inset: number): [Point, Point] {
  if (!(inset > 0)) return [start, end];
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const length = Math.hypot(dx, dy);
  const pull = Math.min(inset, Math.max(0, (length - MIN_FLOATING_ARROW) / 2));
  if (pull <= 0) return [start, end];
  const ux = dx / length;
  const uy = dy / length;
  return [
    { x: start.x + ux * pull, y: start.y + uy * pull },
    { x: end.x - ux * pull, y: end.y - uy * pull },
  ];
}

