import type { FlowGraph, FlowSceneInput } from './types.ts';

export function fromCanvasScene(scene: FlowSceneInput): FlowGraph {
  return {
    direction: scene.options.direction,
    width: scene.options.width,
    height: scene.options.height,
    autoHeight: scene.options.autoHeight,
    gap: scene.options.gap,
    route: scene.options.route,
    nodes: scene.nodes.map((node, index) => ({
      id: node.id,
      markdown: node.markdown,
      index,
      width: node.width,
      height: node.height,
      x: node.x,
      y: node.y,
      dx: node.dx,
      dy: node.dy,
      pinned: node.pinned,
    })),
    edges: scene.edges.map((edge, index) => ({
      index,
      from: edge.from,
      to: edge.to,
      label: edge.label,
      route: edge.route,
      arrows: edge.arrows,
      inset: edge.inset,
    })),
  };
}

src/flow/order.ts.source:
import { edgeKey, type FlowGraph, type FlowRanked } from './types.ts';

function sortByBarycenter(
  members: number[],
  neighborOrder: number[],
  neighbors: number[][],
  authored: number[],
) {
  const position = new Map(neighborOrder.map((node, i) => [node, i]));
  const bary = (node: number) => {
    const connected = neighbors[node].filter((item) => position.has(item));
    if (!connected.length) return (neighborOrder.length - 1) / 2;
    return connected.reduce((sum, item) => sum + (position.get(item) || 0), 0) / connected.length;
  };
  return [...members].sort((a, b) => {
    const delta = bary(a) - bary(b);
    if (Math.abs(delta) > 1e-9) return delta;
    return authored[a] - authored[b];
  });
}

/** Reduce crossings with a stable barycenter sweep. Ties keep the manuscript order. */
export function orderRanks(graph: FlowGraph, ranked: FlowRanked): FlowRanked {
  const authored = graph.nodes.map((node) => node.index);
  const groups = ranked.groups.map((members) => [...members]);
  const forward = graph.nodes.map(() => [] as number[]);
  const backward = graph.nodes.map(() => [] as number[]);
  for (const edge of graph.edges) {
    if (ranked.feedback.has(edgeKey(edge.from, edge.to))) continue;
    const from = graph.nodes.findIndex((node) => node.id === edge.from);
    const to = graph.nodes.findIndex((node) => node.id === edge.to);
    if (from < 0 || to < 0) continue;
    forward[from].push(to);
    backward[to].push(from);
  }
  for (let pass = 0; pass < 6; pass += 1) {
    for (let rank = 1; rank < groups.length; rank += 1) {
      groups[rank] = sortByBarycenter(groups[rank], groups[rank - 1], backward, authored);
    }
    for (let rank = groups.length - 2; rank >= 0; rank -= 1) {
      groups[rank] = sortByBarycenter(groups[rank], groups[rank + 1], forward, authored);
    }
  }
  return { ...ranked, groups };
}

src/flow/place.ts.source:
import {
  FLOW,
  type FlowFrame,
  type FlowGraph,
  type FlowNodeMeasure,
  type FlowRanked,
} from './types.ts';
import { alignBranches } from './align.ts';

function axisGaps(graph: FlowGraph, gap = graph.gap) {
  const rankGap = graph.route === 'auto' ? Math.max(gap, FLOW.RANK_GAP) : gap;
  return { rankGap, crossGap: gap };
}

export function contentHeight(
  graph: FlowGraph,
  groups: number[][],
  sizes: { width: number; height: number }[],
  gap = graph.gap,
) {
  const horizontal = graph.direction === 'right' || graph.direction === 'left';
  const { rankGap, crossGap } = axisGaps(graph, gap);
  const packed = horizontal
    ? Math.max(
        ...groups.map(
          (members) =>
            members.reduce((sum, i) => sum + sizes[i].height, 0) +
            crossGap * Math.max(0, members.length - 1),
        ),
      )
    : groups.reduce((sum, members) => sum + Math.max(...members.map((i) => sizes[i].height)), 0) +
      rankGap * Math.max(0, groups.length - 1);
  const feedbackPad = graph.edges.some((edge) => edge.feedback) ? FLOW.FEEDBACK_PAD * 2 : 0;
  return Math.max(FLOW.MIN_HEIGHT, Math.ceil(packed + FLOW.HEIGHT_PAD + feedbackPad));
}

export function placeNodes(
  graph: FlowGraph,
  measures: FlowNodeMeasure[],
  ranked: FlowRanked,
  gap = graph.gap,
) {
  const horizontal = graph.direction === 'right' || graph.direction === 'left';
  const sizes = measures.map((measure) => ({ width: measure.width, height: measure.height }));
  const height = graph.autoHeight ? contentHeight(graph, ranked.groups, sizes, gap) : graph.height;
  const primarySize = horizontal ? graph.width : height;
  const crossSize = horizontal ? height : graph.width;
  const padding = FLOW.PADDING;
  const groupPrimary = ranked.groups.map((members) =>
    Math.max(...members.map((i) => (horizontal ? sizes[i].width : sizes[i].height))),
  );
  const occupied = groupPrimary.reduce((sum, value) => sum + value, 0);
  const rankCount = ranked.groups.length;
  const inner = Math.max(0, primarySize - padding * 2);
  const { rankGap, crossGap } = axisGaps(graph, gap);
  const packed = occupied + rankGap * Math.max(0, rankCount - 1);
  const usedGap =
    rankCount > 1 && packed > inner + 0.5
      ? Math.max(FLOW.MIN_GAP, (inner - occupied) / (rankCount - 1))
      : rankGap;
  const usedPacked = occupied + usedGap * Math.max(0, rankCount - 1);
  const origin = padding + Math.max(0, (inner - usedPacked) / 2);
  const primaryPositions: number[] = [];
  let primaryCursor = origin;
  groupPrimary.forEach((length, i) => {
    primaryPositions.push(primaryCursor);
    primaryCursor += length + (i < rankCount - 1 ? usedGap : 0);
  });
  const frames = new Map<string, FlowFrame>();
  ranked.groups.forEach((members, groupIndex) => {
    const crossLengths = members.map((i) => (horizontal ? sizes[i].height : sizes[i].width));
    const total =
      crossLengths.reduce((sum, value) => sum + value, 0) + crossGap * (members.length - 1);
    let cross = Math.max(padding, (crossSize - total) / 2);
    members.forEach((nodeIndex, memberIndex) => {
      const node = graph.nodes[nodeIndex];
      const size = sizes[nodeIndex];
      const rawPrimary = primaryPositions[groupIndex];
      const primary =
        graph.direction === 'left' || graph.direction === 'up'
          ? primarySize - rawPrimary - (horizontal ? size.width : size.height)
          : rawPrimary;
      let x = horizontal ? primary : cross;
      let y = horizontal ? cross : primary;
      if (node.pinned && node.x !== undefined) x = node.x;
      if (node.pinned && node.y !== undefined) y = node.y;
      frames.set(node.id, {
        x: x + node.dx,
        y: y + node.dy,
        width: size.width,
        height: size.height,
      });
      cross += crossLengths[memberIndex] + crossGap;
    });
  });
  return alignBranches(graph, ranked, frames, height, crossGap);
}

src/render/lifecycle.ts.source:
export interface Rendered {
  update: () => void;
  dispose: () => void;
}

export class RenderScope implements Rendered {
  private updates: (() => void)[] = [];
  private disposals: (() => void)[] = [];

  add(rendered: Rendered) {
    this.updates.push(rendered.update);
    this.onDispose(rendered.dispose);
  }

  onDispose(dispose: () => void) {
    this.disposals.push(dispose);
  }

  update = () => {
    this.updates.forEach((update) => update());
  };

  dispose = () => {
    const disposals = this.disposals;
    this.disposals = [];
    this.updates = [];
    disposals.forEach((dispose) => dispose());
  };
}

