    }),
    'Built /tmp/talk.html: 2 KiB; 2 slides, 1 asset; all fonts embedded.',
  );
  assert.equal(
    buildReport({
      outPath: '/tmp/talk.html',
      html: 'x',
      blocks: [{ kind: 'manifest' }, { kind: 'slide' }],
    }),
    'Built /tmp/talk.html: 0 KiB; 1 slide, 0 assets; all fonts embedded.',
  );
});

