test/slide-radius.test.ts.source:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Window } from 'happy-dom';
import { cornerRadius, parseRadiusRatio, watchSlideCorners } from '../src/slide-radius.ts';

test('corner radius follows the shorter side', () => {
  assert.equal(cornerRadius(260, 119, 0.12), 14.28);
  assert.equal(cornerRadius(119, 260, 0.12), 14.28);
  assert.equal(cornerRadius(400, 200, 0.12), 24);
  assert.equal(cornerRadius(0, 100, 0.12), 0);
});

test('radius ratio accepts a percent or a fraction', () => {
  assert.equal(parseRadiusRatio('12%'), 0.12);
  assert.equal(parseRadiusRatio('0.12'), 0.12);
  assert.equal(parseRadiusRatio(''), 0.12);
});

test('laid-out cards receive a radius from their own shorter side', () => {
  const window = new Window();
  const previous = {
    document: globalThis.document,
    ResizeObserver: globalThis.ResizeObserver,
    getComputedStyle: globalThis.getComputedStyle,
  };
  Object.assign(globalThis, {
    document: window.document,
    ResizeObserver: window.ResizeObserver,
    getComputedStyle: window.getComputedStyle.bind(window),
  });
  window.document.documentElement.style.setProperty('--slide-radius-ratio', '12%');
  const root = window.document.createElement('div');
  window.document.body.append(root);
  root.innerHTML = `
    <div class="slide-card"></div>
    <div class="canvas-node canvas-shape-ellipse"></div>
    <div class="step-card"></div>
  `;
  const asElement = (selector: string) =>
    root.querySelector(selector) as unknown as HTMLElement;
  const size = (element: HTMLElement, width: number, height: number) => {
    Object.defineProperty(element, 'offsetWidth', { value: width });
    Object.defineProperty(element, 'offsetHeight', { value: height });
  };
  const card = asElement('.slide-card');
  const ellipse = asElement('.canvas-node');
  const step = asElement('.step-card');
  size(card, 260, 119);
  size(ellipse, 200, 80);
  size(step, 80, 200);
  const watched = watchSlideCorners(root as unknown as HTMLElement);
  watched.update();
  assert.equal(card.style.getPropertyValue('--slide-radius'), '14.28px');
  assert.equal(step.style.getPropertyValue('--slide-radius'), '9.6px');
  assert.equal(ellipse.style.getPropertyValue('--slide-radius'), '');
  watched.dispose();
  Object.assign(globalThis, previous);
  window.close();
});

test/session.test.ts.source:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { EditorSession } from '../src/app/session';
import { SourceStore } from '../src/source';

function session() {
  const store = new SourceStore({
    html: null,
    blocks: [
      { id: 'manifest', kind: 'manifest', name: 'manifest', text: '{"title":"Original"}' },
      { id: 'one', kind: 'slide', name: 'One', text: '# One' },
      { id: 'two', kind: 'slide', name: 'Two', text: '# Two' },
    ],
  });
  const session = new EditorSession(store);
  session.readManifest();
  session.activeBlock = 'one';
  return session;
}

test('failed edits restore sources, selection and manifest together', () => {
  const editor = session();
  const before = editor.store.snapshot();
  assert.throws(
    () =>
      editor.mutate(() => {
        editor.store.remove('one');
        editor.store.setText('manifest', '{"title":"Changed"}');
        editor.activeBlock = 'two';
        editor.current = 1;
        editor.readManifest();
        throw new Error('Edit failed');
      }),
    /Edit failed/,
  );
  assert.deepEqual(editor.store.snapshot(), before);
  assert.equal(editor.activeBlock, 'one');
  assert.equal(editor.current, 0);
  assert.equal(editor.manifest.title, 'Original');
  assert.deepEqual(editor.manifest.slides, ['one', 'two']);
  assert.equal(editor.sourceChanged(), false);
});

test('physical reordering is a change and rebasing adopts the new document baseline', () => {
  const editor = session();
  assert.equal(
    editor.mutate(() => editor.store.setText('one', '# One')),
    false,
  );
  assert.equal(
    editor.mutate(() => editor.store.moveBefore('two', 'one')),
    true,
  );
  editor.readManifest();
  assert.equal(editor.currentId(), 'two');
  assert.equal(editor.sourceChanged(), true);
  assert.equal(editor.changedCount(), 1);
  editor.rebase();
  assert.equal(editor.sourceChanged(), false);
  assert.equal(editor.changedCount(), 0);
  assert.deepEqual(editor.boot, editor.store.snapshot());
});

test/render-blocks.test.ts.source:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Window } from 'happy-dom';
import { renderSlide } from '../src/render.ts';
import { SourceStore } from '../src/source.ts';

test('removed model directives stay visible as text while static math still renders', () => {
  const window = new Window({ settings: { disableComputedStyleRendering: true } });
  const originalDocument = globalThis.document;
  Object.assign(globalThis, { document: window.document });
  try {
    const root = window.document.createElement('div');
    const rendered = renderSlide(
      root as unknown as HTMLElement,
      '$E=mc^2$\n\n$$x^2$$\n\n{{wave.gamma}}\n\n```milo:model wave\n{"input":"t"}\n```\n\n::plot{model="wave"}\n\n::slider{param="wave.gamma"}\n\n::equation{model="wave"}',
      {
        store: new SourceStore({ html: null, blocks: [] }),
        present: () => false,
        inspect: () => {},
      },
    );
    assert.equal(root.querySelectorAll('.katex').length, 2);
    assert.match(root.textContent, /\{\{wave\.gamma\}\}/);
    assert.equal(root.querySelector('code')?.textContent.trim(), '{"input":"t"}');
    assert.equal(root.querySelector('.block-error'), null);
    assert.match(root.textContent, /::plot\{model="wave"\}/);
    assert.match(root.textContent, /::slider\{param="wave.gamma"\}/);
    assert.match(root.textContent, /::equation\{model="wave"\}/);
    rendered.dispose();
  } finally {
    Object.assign(globalThis, { document: originalDocument });
    window.close();
  }
});

test('paired blocks ignore closing markers inside long fences and report missing endings', () => {
  const window = new Window({ settings: { disableComputedStyleRendering: true } });
  const originalDocument = globalThis.document;
  Object.assign(globalThis, { document: window.document });
  const context = {
    store: new SourceStore({ html: null, blocks: [] }),
    present: () => false,
    inspect: () => {},
  };
  try {
    for (const name of ['box', 'panel', 'grid', 'stack', 'impact', 'footer', 'canvas']) {
      const root = window.document.createElement('div');
      const rendered = renderSlide(
        root as unknown as HTMLElement,
        `@${name}\n\n~~~~\n@end${name}\n~~~\n~~~~\n\nStill inside\n@end${name}\n\nOutside`,
        context,
      );
      assert.match(root.querySelector('code')?.textContent ?? '', new RegExp(`@end${name}`));
      assert.match(root.textContent, /Still inside/);
      assert.match(root.textContent, /Outside/);
      assert.equal(root.querySelector('.block-error'), null);
      rendered.dispose();
      const broken = window.document.createElement('div');
      renderSlide(broken as unknown as HTMLElement, `@${name}\n\n~~~~\n@end${name}\n~~~~`, context);
      assert.match(
        broken.querySelector('.block-error')?.textContent ?? '',
        new RegExp(`@end${name}`),
      );
    }
    const nested = window.document.createElement('div');
    renderSlide(
      nested as unknown as HTMLElement,
      '@box\nOuter\n\n@box tone=muted\nInner\n@endbox\n\nOuter again\n@endbox',
      context,
    );
    assert.equal(nested.querySelectorAll('.box-block').length, 2);
    assert.match(nested.textContent, /Outer again/);
    const columns = window.document.createElement('div');
    renderSlide(
      columns as unknown as HTMLElement,
      '@columns\n@column\nA\n@endcolumn\n@column\nB\n@endcolumn\n\n~~~~\n@endcolumns\n~~~~',
      context,
    );
    assert.match(columns.querySelector('.block-error')?.textContent ?? '', /@endcolumns/);
  } finally {
    Object.assign(globalThis, { document: originalDocument });
    window.close();
  }
});

test/flow.test.ts.source:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Window } from 'happy-dom';
import { canvasDiagnostics, canvasHeight, layoutCanvas, parseCanvas } from '../src/canvas.ts';
import { parseDiagram } from '../src/diagram.ts';
import { layoutFlowFromCanvas } from '../src/flow/layout.ts';
import {
  estimateEdgeLabel,
  estimateHeightAtWidth,
  unifyGroupedHeights,
} from '../src/flow/measure.ts';
import { fromCanvasScene } from '../src/flow/normalize.ts';
import { FLOW } from '../src/flow/types.ts';
import { validateFlow } from '../src/flow/validate.ts';
import { renderSlide } from '../src/render.ts';
import { SourceStore } from '../src/source.ts';

function render(source: string) {
  const window = new Window({ settings: { disableComputedStyleRendering: true } });
  const originalDocument = globalThis.document,
    originalResizeObserver = globalThis.ResizeObserver;
  Object.assign(globalThis, {
    document: window.document,
    ResizeObserver: window.ResizeObserver,
  });
  const root = window.document.createElement('div');
  const rendered = renderSlide(root as unknown as HTMLElement, source, {
    store: new SourceStore({ html: null, blocks: [] }),
    present: () => false,
    inspect: () => {},
  });
  return {
    root,
    close() {
      rendered.dispose();
      Object.assign(globalThis, {
        document: originalDocument,
        ResizeObserver: originalResizeObserver,
      });
      window.close();
    },
  };
}

test('diagram flow keeps an explicit height and treats omitted height as auto', () => {
  const fixed = parseDiagram(
    `@item a title="入力"
@item b title="実行"
@link a -> b`,
    'layout=flow height=480',
  );
  assert.equal(fixed.options.autoHeight, false);
  assert.equal(fixed.options.height, 480);

  const omitted = parseDiagram(`@item a title="入力"`, 'layout=flow');
  assert.equal(omitted.options.autoHeight, true);

  const explicitAuto = parseDiagram(`@item a title="入力"`, 'layout=flow height=auto');
  assert.equal(explicitAuto.options.autoHeight, true);

  assert.throws(() => parseDiagram(`@item a title="A"`, 'layout=ring height=auto'), /layout=flow/);
});

test('fixed flow height stays 480 and reports when nodes leave the frame', () => {
  const scene = parseCanvas(
    `@node a\n### 節点A\n-->\n@node b\n### 節点B\n-->\n@node c\n### 節点C\n-->\n@node d\n### 節点D`,
    'layout=flow direction=down height=480',
  );
  assert.equal(scene.options.autoHeight, false);
  assert.equal(canvasHeight(scene, [60, 60, 60, 60]), 480);
  const layout = layoutFlowFromCanvas(scene, [60, 60, 60, 60]);
  assert.equal(layout.height, 480);
  assert.equal(
    layout.diagnostics.some((item) => item.code === 'FRAME_OVERFLOW'),
    false,
  );

  const tight = parseCanvas(
    `@node a\n### 節点A\n-->\n@node b\n### 節点B\n-->\n@node c\n### 節点C\n-->\n@node d\n### 節点D`,
    'layout=flow direction=down height=120',
  );
  const overflow = layoutFlowFromCanvas(tight, [80, 80, 80, 80]);
  assert.equal(overflow.height, 120);
  assert.ok(overflow.diagnostics.some((item) => item.code === 'FRAME_OVERFLOW'));
});

test('diagram height=480 is not overwritten by canvas auto-height', () => {
  const { root, close } = render(`@diagram layout=flow direction=right height=480
@item a title="入力"
@item b title="実行"
@link a -> b
@enddiagram`);
  try {
    const canvas = root.querySelector('.milo-canvas') as unknown as HTMLElement;
    assert.ok(canvas);
    assert.equal(canvas.style.aspectRatio.replace(/\s/g, ''), '1280/480');
    assert.equal(canvas.style.getPropertyValue('--diagram-display-width'), '1280px');
    assert.ok(canvas.classList.contains('diagram-layout-flow'));
  } finally {
    close();
  }
});

test('unreadable fixed-height flow still reports a diagnostic instead of succeeding silently', () => {
  const scene = parseCanvas('A\n-->\nB', 'height=40');
  const diagnostics = canvasDiagnostics(scene, [80, 90]);
  assert.ok(
    diagnostics.some((item) => item.code === 'FRAME_OVERFLOW' || item.code === 'TEXT_OVERFLOW'),
  );
  const { root, close } = render(`@canvas height=40
A
-->
B
@endcanvas`);
  try {
    assert.equal(
      root.querySelector('.milo-canvas')?.getAttribute('data-canvas-overflow') !== null,
      true,
    );
    assert.match(
      root.querySelector('.canvas-overflow-hint')?.textContent || '',
      /収まりません|切れています|余白が足りません/,
    );
  } finally {
    close();
  }
});

test('four serial flow nodes fit without clipping Japanese titles', () => {
  const scene = parseCanvas(
    `@node a\n### 節点A\n-->\n@node b\n### 節点B\n-->\n@node c\n### 節点C\n-->\n@node d\n### 節点D`,
    'layout=flow direction=right width=1000',
  );
  const layout = layoutFlowFromCanvas(scene);
  const frames = [...layout.nodeFrames.values()];
  assert.equal(frames.length, 4);
  for (const frame of frames) {
    assert.ok(frame.width >= 180 && frame.width <= 360);
    assert.ok(frame.x >= 0 && frame.x + frame.width <= 1000 + 1);
    assert.ok(frame.y >= 0);
  }
  const right = Math.max(...frames.map((frame) => frame.x + frame.width));
  assert.ok(right <= 1000 + 1);
  assert.equal(
    layout.diagnostics.some(
      (item) => item.code === 'TEXT_OVERFLOW' || item.code === 'FRAME_OVERFLOW',
    ),
    false,
  );
});

test('long Japanese titles get a wider node than short ones', () => {
  const scene = parseCanvas(
    `@node a\n### 短い題\n-->\n@node b\n### これは幅の差を出すための長い日本語タイトルです\n-->\n@node c\n### 中くらいの題`,
    'layout=flow direction=right',
  );
  const layout = layoutFlowFromCanvas(scene);
  const a = layout.nodeFrames.get('a')!;
  const b = layout.nodeFrames.get('b')!;
  const c = layout.nodeFrames.get('c')!;
  assert.ok(b.width > a.width);
  assert.ok(b.width > c.width);
  assert.ok(b.width - a.width <= FLOW.WIDTH_VARIANCE);
  assert.ok(b.height < estimateHeightAtWidth(scene.nodes[1].markdown, FLOW.MIN_WIDTH));
});

test('long flow body grows height instead of shrinking type', () => {
  const scene = parseCanvas(
    `@node a\n### 入力\n長い日本語の本文を折り返しても文字サイズは変えない。\n-->\n@node b\n### 実行\nこちらも説明を少し長く書く。`,
    'layout=flow direction=right',
  );
  const layout = layoutFlowFromCanvas(scene);
  const a = layout.nodeFrames.get('a')!;
  assert.ok(a.height >= 76);
  assert.equal(
    layout.diagnostics.some((item) => item.code === 'TEXT_OVERFLOW'),
    false,
  );
});

test('grouped heights match unless the gap is extreme or there is no link', () => {
  assert.deepEqual(unifyGroupedHeights([100, 132], [[0, 1]]), [132, 132]);
  assert.deepEqual(unifyGroupedHeights([80, 200], [[0, 1]]), [80, 200]);
  assert.deepEqual(unifyGroupedHeights([100, 132], []), [100, 132]);
  assert.deepEqual(
    unifyGroupedHeights(
      [100, 120, 200],
      [
        [0, 1],
        [1, 2],
      ],
    ),
    [100, 200, 200],
  );
  assert.deepEqual(unifyGroupedHeights([147, 241], [[0, 1]], FLOW.BOX_HEIGHT_VARIANCE), [241, 241]);
  assert.deepEqual(unifyGroupedHeights([89, 336], [[0, 1]], FLOW.BOX_HEIGHT_VARIANCE), [89, 336]);
});

test('linked nodes share height when the difference is small', () => {
  const scene = parseCanvas(`@node a\n### A\n-->\n@node b\n### B`, 'layout=flow direction=right');
  const layout = layoutFlowFromCanvas(scene, [100, 132]);
  assert.equal(layout.nodeFrames.get('a')!.height, 132);
  assert.equal(layout.nodeFrames.get('b')!.height, 132);
});

test('linked nodes keep their height when the difference is extreme', () => {
  const scene = parseCanvas(`@node a\n### A\n-->\n@node b\n### B`, 'layout=flow direction=right');
  const layout = layoutFlowFromCanvas(scene, [80, 200]);
  assert.equal(layout.nodeFrames.get('a')!.height, 80);
  assert.equal(layout.nodeFrames.get('b')!.height, 200);
});

test('unlinked nodes do not share height', () => {
  const scene = parseCanvas(`@node a\n### A\n@node b\n### B`, 'layout=flow direction=right');
  const layout = layoutFlowFromCanvas(scene, [100, 132]);
  assert.equal(layout.nodeFrames.get('a')!.height, 100);
  assert.equal(layout.nodeFrames.get('b')!.height, 132);
});

test('explicit node height is not overwritten by linked neighbors', () => {
  const scene = parseCanvas(
    `@node a height=90\n### A\n-->\n@node b\n### B`,
    'layout=flow direction=right',
  );
  const layout = layoutFlowFromCanvas(scene, [90, 132]);
  assert.equal(layout.nodeFrames.get('a')!.height, 90);
  assert.equal(layout.nodeFrames.get('b')!.height, 132);
});

test('branch and merge stay on shared ranks without crossing', () => {
  const scene = parseCanvas(
    `@node a\n### 入力\n@node b\n### 経路A\n@node c\n### 経路B\n@node d\n### 統合\n@edge a --> b\n@edge a --> c\n@edge b --> d\n@edge c --> d`,
    'layout=flow direction=right',
  );
  const layout = layoutFlowFromCanvas(scene);
  const a = layout.nodeFrames.get('a')!;
  const b = layout.nodeFrames.get('b')!;
  const c = layout.nodeFrames.get('c')!;
  const d = layout.nodeFrames.get('d')!;
  assert.ok(Math.abs(b.x - c.x) < 1);
  assert.ok(a.x + a.width < b.x);
  assert.ok(b.x + b.width < d.x);
  const ab =
    (b.y + b.height / 2 - (a.y + a.height / 2)) * (c.y + c.height / 2 - (a.y + a.height / 2));
  assert.ok(ab < 0);
});

test('crossing edges are uncrossed by barycenter order', () => {
  const scene = parseCanvas(
    `@node a\nA\n@node b\nB\n@node c\nC\n@node d\nD\n@edge a --> d\n@edge b --> c`,
    'layout=flow direction=right',
  );
  const layout = layoutFlowFromCanvas(scene);
  const a = layout.nodeFrames.get('a')!;
  const b = layout.nodeFrames.get('b')!;
  const c = layout.nodeFrames.get('c')!;
  const d = layout.nodeFrames.get('d')!;
  const aAbove = a.y + a.height / 2 < b.y + b.height / 2;
  const dAbove = d.y + d.height / 2 < c.y + c.height / 2;
  assert.equal(aAbove, dAbove);
});

test('cycles become a ranked line plus a feedback diagnostic', () => {
  const scene = parseCanvas(
    `@node plan\n### 計画\n@node do\n### 実行\n@node see\n### 検証\n@edge plan --> do\n@edge do --> see\n@edge see --> plan`,
    'layout=flow direction=right',
  );
  const layout = layoutFlowFromCanvas(scene);
  assert.ok(layout.diagnostics.some((item) => item.code === 'CYCLE_DETECTED'));
  const xs = ['plan', 'do', 'see'].map((id) => layout.nodeFrames.get(id)!.x);
  assert.ok(xs[0] < xs[1]);
  assert.ok(xs[1] < xs[2]);
});

test('inset parks a flow arrow in the gap instead of on the cards', () => {
  const scene = parseCanvas(
    `@node a\n### 入力\n@node b\n### 実行\n@edge a --> b inset=28`,
    'layout=flow direction=right width=520 gap=28',
  );
  assert.equal(scene.edges[0].inset, 28);
  const diagram = parseDiagram(
    `@item a title="入力"\n@item b title="実行"\n@link a -> b inset=28`,
    'layout=flow',
  );
  assert.equal(diagram.links[0].inset, 28);
  assert.throws(
    () =>
      parseDiagram(
        `@item a title="入力"\n@item b title="実行"\n@link a -> b inset=-4`,
        'layout=flow',
      ),
    /inset は 0 以上/,
  );
  const layout = layoutFlowFromCanvas(scene);
  const a = layout.nodeFrames.get('a')!;
  const b = layout.nodeFrames.get('b')!;
  const numbers = layout.edgePaths[0].path.match(/-?\d+(?:\.\d+)?/g)!.map(Number);
  const startX = numbers[0];
  const endX = numbers[numbers.length - 2];
  assert.ok(startX > a.x + a.width + 8);
  assert.ok(endX < b.x - 8);
  const gapMid = (a.x + a.width + b.x) / 2;
  assert.ok(Math.abs((startX + endX) / 2 - gapMid) < 4);
});

test('route=curve keeps a cubic for a two-point edge', () => {
  const scene = parseCanvas(
    `@node a\n### 入力\n-->\n@node b\n### 実行`,
    'layout=flow direction=right route=curve',
  );
  const layout = layoutFlowFromCanvas(scene);
  assert.match(layout.edgePaths[0].path, / C /);
  assert.equal(layout.edgePaths[0].path.includes(' L '), false);
});

test('flow edges use the thin gray arrows from outside notes', () => {
  const { root, close } = render(`@diagram layout=flow
@item a title="入力"
@item b title="実行"
@link a -> b
@enddiagram`);
  try {
    const canvas = root.querySelector('.milo-canvas') as unknown as HTMLElement;
    const marker = root.querySelector('marker') as unknown as SVGMarkerElement;
    assert.ok(canvas.classList.contains('canvas-layout-flow'));
    assert.equal(marker?.getAttribute('markerWidth'), '5');
    assert.equal(marker?.getAttribute('markerHeight'), '5');
    assert.ok(root.querySelector('.canvas-edge')?.getAttribute('marker-end'));
  } finally {
    close();
  }
});

test('diagram route=curve is forwarded to the flow engine', () => {
  const parsed = parseDiagram(
    `@item a title="入力"
@item b title="実行"
@link a -> b`,
    'layout=flow route=curve',
  );
  assert.equal(parsed.options.route, 'curve');
  const { root, close } = render(`@diagram layout=flow route=curve
@item a title="入力"
@item b title="実行"
@link a -> b
@enddiagram`);
  try {
    const path = root.querySelector('.canvas-edge')?.getAttribute('d') || '';
    assert.match(path, / C /);
  } finally {
    close();
  }
});

test('route=curve falls back when a smoothed detour would cut a node', () => {
  const scene = parseCanvas(
    `@node plan\n### 計画\n@node do\n### 実行\n@node see\n### 検証\n@edge plan --> do\n@edge do --> see\n@edge see --> plan`,
    'layout=flow direction=right route=curve',
  );
  const layout = layoutFlowFromCanvas(scene);
  const back = layout.edgePaths.find((path) => path.from === 'see' && path.to === 'plan')!;
  const mid = layout.nodeFrames.get('do')!;
  assert.equal(
    layout.diagnostics.some((item) => item.code === 'EDGE_COLLISION'),
    false,
  );
  assert.ok(back.label.y > mid.y + mid.height);
  assert.ok(Math.max(mid.y, back.label.y) > mid.y + mid.height);
});

test('flow edges leave from the node perimeter and avoid a third node', () => {
  const scene = parseCanvas(
    `@node a\n### 入力\n@node b\n### 経路A\n@node c\n### 経路B\n@node d\n### 統合\n@edge a --> b\n@edge a --> c\n@edge b --> d\n@edge c --> d`,
    'layout=flow direction=right route=elbow',
  );
  const layout = layoutFlowFromCanvas(scene);
  const a = layout.nodeFrames.get('a')!;
  const b = layout.nodeFrames.get('b')!;
  const first = layout.edgePaths.find((path) => path.from === 'a' && path.to === 'b')!;
  const nums = [...first.path.matchAll(/(-?\d+(?:\.\d+)?)/g)].map((match) => Number(match[1]));
  assert.ok(Math.abs(nums[0] - (a.x + a.width)) < 2);
  assert.ok(Math.abs(nums[nums.length - 2] - b.x) < 2);
  assert.equal(
    layout.diagnostics.some((item) => item.code === 'EDGE_COLLISION'),
    false,
  );
});

test('feedback edges travel around the figure instead of through nodes', () => {
