    assert.equal(root.querySelector('.box-tone-accent, .card-tone-pale'), null);
  } finally {
    close();
  }
});

test('grid, stack and panel nest and stretch as equal-height layout', () => {
  const { root, close } = render(`@grid columns=2
@panel
### 左
@stack
@box tone=default
上
@endbox
@box tone=dark
下
@endbox
@endstack
@endpanel
@panel tone=accent
### 右
本文
@endpanel
@endgrid`);
  try {
