test('unhighlighted steps sit on a transparent field instead of a muted card', () => {
  const components = readFileSync(new URL('../src/styles/components.css', import.meta.url), 'utf8');
  assert.match(components, /\.step-card \{[^}]*background: transparent/s);
  assert.doesNotMatch(components, /\.step-card\.is-highlight \{[^}]*border-color/s);
  assert.match(components, /\.step-badge::after \{[^}]*content: '\. '[^}]*white-space: pre/s);
  assert.doesNotMatch(components, /\.step-badge \{[^}]*border-radius: 50%/s);
  assert.match(
    components,
    /\.step-card\.is-highlight \.step-badge,\n\.step-card\.is-highlight \.step-title \{[^}]*color: var\(--accent\)/s,
  );
  assert.match(
    components,
    /\.step-card\.is-highlight \.step-badge::after \{[^}]*color: var\(--accent\)/s,
  );
  assert.doesNotMatch(components, /\.step-card \{[^}]*background: var\(--slide-card\)/s);
});

test('steps lay out numbered cards, arrows and a highlighted current step', () => {
  const { root, close } = render(`@steps highlight=2
@step title="考え方"
目的と制約
トレードオフ・決め方
@step title="3つのケース"
アプリ / セキュリティ / Runnerログ
@step title="まとめ"
全体像
@endsteps`);
  try {
    const cards = [...root.querySelectorAll('.step-card')];
    assert.equal(cards.length, 3);
    assert.equal(root.querySelectorAll('.step-arrow').length, 2);
    assert.equal(cards[0].querySelector('.step-badge')?.textContent, '1');
    assert.equal(cards[1].querySelector('.step-title')?.textContent, '3つのケース');
    assert.equal(cards[1].classList.contains('is-highlight'), true);
    assert.equal(cards[0].classList.contains('is-highlight'), false);
    assert.match(cards[2].textContent, /全体像/);
    assert.ok(cards[0].querySelector('.step-body br'));
    assert.equal(
      root.querySelector('.steps-block')?.classList.contains('steps-place-center'),
      false,
    );
