});

test('place=center anchors the steps row in the middle of the slide', () => {
  const { root, close } = render(`@steps place=center
@step title="収集"
読む
@step title="整理"
分ける
@endsteps`);
  try {
    assert.equal(
      root.querySelector('.steps-block')?.classList.contains('steps-place-center'),
      true,
    );
  } finally {
    close();
  }
  const bad = render(`@steps place=bottom
@step title="収集"
読む
@endsteps`);
  try {
    assert.match(
      bad.root.querySelector('.block-error')?.textContent ?? '',
      /place は start \/ center/,
    );
  } finally {
    bad.close();
  }
});

test('steps report missing endings, titles and highlight range', () => {
  for (const [source, pattern] of [
    ['@steps\n@step title="A"\n本文\n', /@endsteps/],
    ['@steps\n本文だけ\n@endsteps', /@step/],
    ['@steps\n@step\n本文\n@endsteps', /title/],
    ['@steps highlight=4\n@step title="A"\nA\n@step title="B"\nB\n@endsteps', /1〜2/],
  ] as const) {
    const { root, close } = render(source);
    try {
      assert.match(root.querySelector('.block-error')?.textContent ?? '', pattern);
    } finally {
      close();
    }
  }
});

