  assert.throws(() => parseDiagram(source, 'layout=flow gap=-1'), /gap/);
  assert.throws(() => parseDiagram(source, 'layout=flow node-width=100'), /node-width/);
  assert.throws(() => parseDiagram(source, 'layout=ring gap=24'), /layout=flow/);
