  assert.ok(s.get('slide-09').text.includes('- [ ]'));
  assert.ok(s.get('slide-10').text.includes('@diagram'));
  assert.ok(s.get('slide-12').text.includes('note=outside'));
  assert.ok(s.get('slide-13').text.includes('layout=flow'));
  assert.ok(s.get('slide-15').text.includes('direction=down'));
  assert.ok(s.get('slide-16').text.includes('フィードバック'));
  assert.ok(s.get('slide-17').text.includes('layout=radial'));
  assert.ok(s.get('slide-19').text.includes('layout=field'));
  assert.ok(s.get('slide-20').text.includes('@zone'));
  assert.ok(s.get('slide-21').text.includes('cluster-region=halo'));
  assert.equal(json(s.get('manifest').text).title, '小さな実験室');
  assert.equal(Object.hasOwn(json(s.get('manifest').text), 'present'), false);
