test('flow, free and hybrid node placement share one frame model', () => {
  const flow = parseCanvas('@node a\nA\n@node b dx=12 dy=5\nB\n@edge a --> b', 'direction=down');
  const frames = layoutCanvas(flow, [80, 90]);
