  assert.ok(frames[1].y > frames[0].y);
  assert.equal(frames[0].height, 90);
  assert.equal(frames[1].height, 90);

  const free = parseCanvas(
    '@node a frame=10,20,210,100\nA\n@node b x=300 y=40 pinned\nB',
    'layout=free',
  );
